import csv
from pathlib import Path
out=Path('codex_output/staged_counts')
out.mkdir(parents=True, exist_ok=True)
with open('inputs/count.csv', newline='') as f:
    r=csv.reader(f)
    header=next(r)
    samples=header[1:]
    handles={s: open(out/f'{s}.tsv','w', newline='') for s in samples}
    writers={s: csv.writer(handles[s], delimiter='\\t', lineterminator='\\n') for s in samples}
    for s in samples:
        writers[s].writerow(['geneID', s])
    for row in r:
        gene=row[0]
        for s,v in zip(samples,row[1:]):
            writers[s].writerow([gene,v])
for h in handles.values(): h.close()
print('\\n'.join(str(out/f'{s}.tsv') for s in samples))
PY"

